Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <cstdio>
#include <algorithm>
#include <vector>
#include <cstring>
#include <queue>
using namespace std;

using dint = int;
using dint64 = long long;
using duint64 = unsigned long long;
using dpoint = pair<int, int>;

const int MAXN = 11;
const int INFTY = 1e9;
const int NODECAP = 2 * MAXN * MAXN;

struct arc {
    int dest;
    int cap;
    int flow;
    int rev;
    arc() : dest(0), cap(0), flow(0), rev(0) {}
    arc(int d, int c, int f, int r) : dest(d), cap(c), flow(f), rev(r) {}
};

vector<arc> adj[NODECAP];
int level[NODECAP], cur[NODECAP], src, dst, sz;
queue<int> q;

inline void link(int u, int v, int c) {
    adj[u].emplace_back(v, c, 0, 0);
    adj[v].emplace_back(u, 0, 0, 0);
    adj[u].back().rev = adj[v].size() - 1;
    adj[v].back().rev = adj[u].size() - 1;
}

bool mkLevel() {
    fill(level, level + dst + 1, INFTY);
    level[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : adj[u]) {
            int v = e.dest;
            int rc = e.cap - e.flow;
            if (level[v] == INFTY && rc > 0) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[dst] != INFTY;
}

int dfs(int u, int f) {
    if (u == dst) return f;
    for (int& i = cur[u]; i < (int)adj[u].size(); ++i) {
        auto& e = adj[u][i];
        int v = e.dest;
        int rc = e.cap - e.flow, df;
        if (level[v] == level[u] + 1 && rc > 0 && (df = dfs(v, min(f, rc)))) {
            e.flow += df;
            adj[v][e.rev].flow -= df;
            return df;
        }
    }
    return 0;
}

int dinic() {
    int flow = 0;
    while (mkLevel()) {
        memset(cur, 0, sizeof(cur));
        int f;
        while ((f = dfs(src, INFTY))) flow += f;
    }
    return flow;
}

queue<dpoint> qpath;
const int ddX[] = {-1, 1, 0, 0};
const int ddY[] = {0, 0, -1, 1};
int dist[MAXN][MAXN][MAXN][MAXN], tlim;
char matA[MAXN][MAXN], matB[MAXN][MAXN];
dpoint hazard;
bool ok(dpoint p) {
    return p.first >= 0 && p.first < sz && p.second >= 0 && p.second < sz && matA[p.first][p.second] != 'Y' && matA[p.first][p.second] != 'Z';
}
void bfsPath(int sx, int sy) {
    for (int i = 0; i < sz; ++i)
        for (int j = 0; j < sz; ++j)
            dist[sx][sy][i][j] = INFTY;
    dist[sx][sy][sx][sy] = 0;
    qpath.push({sx, sy});
    while (!qpath.empty()) {
        dpoint p = qpath.front(); qpath.pop();
        if (dist[sx][sy][p.first][p.second] == dist[hazard.first][hazard.second][p.first][p.second] && (hazard.first != sx || hazard.second != sy)) continue;
        for (int k = 0; k < 4; ++k) {
            dpoint np = {p.first + ddX[k], p.second + ddY[k]};
            if (ok(np) && dist[sx][sy][np.first][np.second] == INFTY && dist[sx][sy][p.first][p.second] + 1 <= dist[hazard.first][hazard.second][np.first][np.second]) {
                dist[sx][sy][np.first][np.second] = dist[sx][sy][p.first][p.second] + 1;
                qpath.push(np);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> sz >> tlim;
    int px, py;
    for (int i = 0; i < sz; ++i)
        for (int j = 0; j < sz; ++j) {
            cin >> matA[i][j];
            if (matA[i][j] == 'Z') px = i, py = j;
        }
    for (int i = 0; i < sz; ++i)
        for (int j = 0; j < sz; ++j)
            cin >> matB[i][j];
    hazard = {px, py};
    bfsPath(px, py);
    for (int i = 0; i < sz; ++i)
        for (int j = 0; j < sz; ++j)
            dist[hazard.first][hazard.second][i][j] = min(dist[hazard.first][hazard.second][i][j], tlim);
    for (int i = 0; i < sz; ++i)
        for (int j = 0; j < sz; ++j)
            if (ok({i, j})) bfsPath(i, j);
    src = 0;
    dst = 2 * sz * sz + 1;
    for (int i = 0; i < sz; ++i)
        for (int j = 0; j < sz; ++j) {
            if (matA[i][j] != '0') link(src, i * sz + j + 1, matA[i][j] - '0');
            if (matB[i][j] != '0') link(i * sz + j + 1 + sz * sz, dst, matB[i][j] - '0');
        }
    for (int i = 0; i < sz; ++i)
        for (int j = 0; j < sz; ++j)
            for (int i1 = 0; i1 < sz; ++i1)
                for (int j1 = 0; j1 < sz; ++j1)
                    if (ok({i, j}) && ok({i1, j1}) && dist[i][j][i1][j1] <= dist[px][py][i1][j1])
                        link(i * sz + j + 1, i1 * sz + j1 + 1 + sz * sz, INFTY);
    cout << dinic();
    return 0;
}
